using TableStorage.Fluent;
using TableStorage.Tests.Models;

namespace TableStorage.Tests;

/// <summary>
/// Covers the fluent entities generated by the TableStorage.Fluent source generator, including the arities requested through <c>GenerateFluentEntities</c>.
/// </summary>
public class FluentGeneratedEntityTests
{
    private static FluentTestModelA CreateA() => new() { PrettyPartitionA = "p", PrettyRowA = "a", TypeA = "A", PropertyA = 1 };
    private static FluentTestModelB CreateB() => new() { PrettyPartitionB = "p", PrettyRowB = "b", TypeB = "B", PropertyB = true };

    [Fact]
    public void FiveTypes_ImplicitConversion_UsesMatchingBackingType()
    {
        FluentTableEntity<Model, Model2, Model3, FluentTestModelA, FluentTestModelB> entity = CreateB();

        Assert.Equal(FluentBackingType.Fifth, entity.GetBackingType());
        Assert.Equal(typeof(FluentTestModelB), entity.GetActualType());
        Assert.Equal(nameof(FluentTestModelB), entity.GetDiscriminatorType());
        Assert.Equal(nameof(FluentTestModelB), entity["$type"]);
        Assert.Equal(5, entity.SwitchCase(case4: _ => 4, case5: _ => 5));
        Assert.Equal(-1, entity.SwitchCaseOrDefault(case4: _ => 4, defaultCase: () => -1));
        Assert.Throws<InvalidCastException>(() => (FluentTestModelA)entity);
        Assert.NotNull((FluentTestModelB)entity);
    }

    [Fact]
    public void SixteenTypes_Compile()
    {
        FluentRowTableEntity<Model, Model2, Model3, Model, Model2, Model3, Model, Model2, Model3, Model, Model2, Model3, Model, Model2, Model3, FluentTestModelA> entity = CreateA();

        Assert.Equal(FluentBackingType.Sixteenth, entity.GetBackingType());
        Assert.Equal(nameof(FluentTestModelA), entity.RowKey);
    }

    [Fact]
    public void DollarType_SetThroughIndexer_CreatesEntityWithBufferedKeys()
    {
        FluentTableEntity<FluentTestModelA, FluentTestModelB> entity = new()
        {
            PartitionKey = "p",
            RowKey = "r"
        };

        entity["$type"] = nameof(FluentTestModelB);

        Assert.Equal(FluentBackingType.Second, entity.GetBackingType());
        Assert.Equal("p", entity.PartitionKey);
        Assert.Equal("r", entity.RowKey);
        Assert.Contains("$type", entity.Keys);
        Assert.Throws<InvalidOperationException>(() => entity["$type"] = nameof(FluentTestModelA));
    }

    [Fact]
    public void DollarType_UnknownType_Throws()
    {
#pragma warning disable IDE0028 // Not a collection, it only implements IDictionary for the Table SDK
        FluentTableEntity<FluentTestModelA, FluentTestModelB> entity = new();
#pragma warning restore IDE0028

        Assert.Throws<InvalidOperationException>(() => entity["$type"] = "Unknown");
        Assert.Equal(FluentBackingType.NotInitialized, entity.GetBackingType());
    }

    [Fact]
    public void PartitionDiscriminator_SetThroughPartitionKey_CreatesEntity()
    {
        FluentPartitionTableEntity<FluentTestModelA, FluentTestModelB> entity = new()
        {
            RowKey = "r",
            PartitionKey = nameof(FluentTestModelA)
        };

        Assert.Equal(FluentBackingType.First, entity.GetBackingType());
        Assert.Equal(nameof(FluentTestModelA), entity.PartitionKey);
        Assert.Equal("r", entity.RowKey);
        Assert.DoesNotContain("$type", entity.Keys);
    }

    [Fact]
    public void PartitionDiscriminator_Constructor_SetsPartitionKey()
    {
        FluentPartitionTableEntity<FluentTestModelA, FluentTestModelB> entity = CreateB();

        Assert.Equal(nameof(FluentTestModelB), ((Azure.Data.Tables.ITableEntity)(FluentTestModelB)entity).PartitionKey);
    }

    [Fact]
    public void WhereTypeIs_WithTypeThatIsNotPartOfTheEntity_Throws()
    {
        Assert.Throws<ArgumentException>(() => FluentQuery.WhereTypeIs<FluentTableEntity<FluentTestModelA, FluentTestModelB>, Model>(null!));
    }
}
